export const DEP_TYPE_TO_NUM = {
    code: 0x00,
    depGroup: 0x01,
};
export const NUM_TO_DEP_TYPE = {
    0x00: "code",
    0x01: "depGroup",
};
export const DEP_TYPES = Object.keys(DEP_TYPE_TO_NUM);
